#!/usr/bin/env node

/**
 * Figma → Swift Token Sync Script
 *
 * Reads Figma DS variables via MCP export (JSON) and generates Swift token files.
 *
 * Usage:
 *   1. Export tokens from Figma: run `use_figma` to dump variables as JSON → figma-tokens.json
 *   2. Run: node scripts/sync-figma-tokens.js
 *   3. Review generated files and commit
 *
 * Or use with Claude Code:
 *   "sync figma tokens" → CDO skill reads Figma, generates JSON, runs this script
 *
 * Input:  figma-tokens.json (generated by Figma MCP export)
 * Output: Reports drift between Figma and Swift code
 */

const fs = require('fs');
const path = require('path');

const TOKENS_FILE = path.join(__dirname, '..', 'figma-tokens.json');
const THEME_FILE = path.join(__dirname, '..', 'Hexbound', 'Hexbound', 'Theme', 'DarkFantasyTheme.swift');
const LAYOUT_FILE = path.join(__dirname, '..', 'Hexbound', 'Hexbound', 'Theme', 'LayoutConstants.swift');

