  'bg/primary': 'bgPrimary',
  'bg/secondary': 'bgSecondary',
  'bg/tertiary': 'bgTertiary',
  'bg/elevated': 'bgElevated',
  'bg/disabled': 'bgDisabled',
  'bg/dark-panel': 'bgDarkPanel',

  // Gold
  'gold/default': 'gold',
  'gold/bright': 'goldBright',
  'gold/dim': 'goldDim',
  'gold/glow-orange': 'glowOrange',

  // Feedback
  'feedback/danger': 'danger',
  'feedback/success': 'success',
  'feedback/info': 'info',
  'feedback/cyan': 'cyan',
  'feedback/purple': 'purple',
  'feedback/stamina': 'stamina',

  // Text
  'text/primary': 'textPrimary',
  'text/secondary': 'textSecondary',
  'text/tertiary': 'textTertiary',
  'text/disabled': 'textDisabled',
  'text/gold': 'textGold',
  'text/on-gold': 'textOnGold',
  'text/danger': 'textDanger',
  'text/success': 'textSuccess',
  'text/warning': 'textWarning',
  'text/status-good': 'textStatusGood',
  'text/dim-label': 'textDimLabel',
  'text/tertiary-aa': 'textTertiaryAA',

  // Border
  'border/subtle': 'borderSubtle',
  'border/medium': 'borderMedium',
  'border/strong': 'borderStrong',
  'border/ornament': 'borderOrnament',
  'border/card': 'bgCardBorder',
  'border/dark-panel': 'bgDarkPanelBorder',

  // Rarity
  'rarity/common': 'rarityCommon',
  'rarity/uncommon': 'rarityUncommon',
  'rarity/rare': 'rarityRare',
  'rarity/epic': 'rarityEpic',
  'rarity/legendary': 'rarityLegendary',

  // Class
  'class/warrior': 'classWarrior',
  'class/rogue': 'classRogue',
  'class/mage': 'classMage',
  'class/tank': 'classTank',

  // Rank
  'rank/bronze': 'rankBronze',
  'rank/silver': 'rankSilver',
  'rank/gold': 'rankGold',
  'rank/platinum': 'rankPlatinum',
  'rank/diamond': 'rankDiamond',
  'rank/grandmaster': 'rankGrandmaster',

  // Button chrome
  'btn/danger-fill': 'btnDangerFill',
  'btn/danger-stroke': 'btnDangerStroke',
  'btn/danger-accent': 'btnDangerAccent',
  'btn/orange-primary': 'btnOrangePrimary',
  'btn/orange-bright': 'btnOrangeBright',
  'btn/orange-glow': 'btnOrangeGlow',
  'btn/orange-stroke': 'btnOrangeStroke',
  'btn/orange-dark': 'btnOrangeDark',
  'btn/orange-mid': 'btnOrangeMid',
  'btn/orange-base': 'btnOrangeBase',
  'btn/purple-dark': 'btnPurpleDark',
  'btn/purple-bright': 'btnPurpleBright',
  'btn/purple-stroke': 'btnPurpleStroke',

  // Premium
  'premium/pink': 'premiumPink',
  'premium/bg': 'bgPremium',
  'premium/bg-deep': 'bgPremiumDeep',
  'premium/border': 'borderPremium',

  // Dungeon
  'dungeon/bg-deep': 'bgDungeonDeep',
  'dungeon/bg-purple': 'bgDungeonPurple',
