  'vfx/poison': 'vfxPoisonGlow',
  'vfx/burn': 'vfxBurnGlow',
  'vfx/stun': 'vfxStunGlow',

  // Zone
  'zone/head': 'zoneHead',
  'zone/chest': 'zoneChest',
  'zone/legs': 'zoneLegs',

  // Misc
  'misc/xp-ring': 'xpRing',
  'misc/xp-ring-track': 'xpRingTrack',
