const FIGMA_TO_SWIFT_SPACING = {
  'space/2xs': 'space2XS',
  'space/xs': 'spaceXS',
  'space/sm': 'spaceSM',
  'space/ms': 'spaceMS',
  'space/md': 'spaceMD',
  'space/lg': 'spaceLG',
  'space/xl': 'spaceXL',
  'space/2xl': 'space2XL',
  'spacing/2xs': 'space2XS',
  'spacing/xs': 'spaceXS',
  'spacing/sm': 'spaceSM',
  'spacing/ms': 'spaceMS',
  'spacing/md': 'spaceMD',
  'spacing/lg': 'spaceLG',
  'spacing/xl': 'spaceXL',
  'spacing/2xl': 'space2XL',
  'radius/xs': 'radiusXS',
  'radius/sm': 'radiusSM',
  'radius/md': 'radiusMD',
  'radius/lg': 'radiusLG',
  'radius/xl': 'radiusXL',
  'radius/2xl': 'radius2XL',
};

// Additional primitive name mappings for gradient and duplicate tokens
FIGMA_TO_SWIFT_COLOR['bg/card-gradient-start'] = 'bgCardGradientStart';
FIGMA_TO_SWIFT_COLOR['bg/card-gradient-end'] = 'bgCardGradientEnd';

// ─── Helpers ───

function hexToInt(hex) {
  return parseInt(hex.replace('#', ''), 16);
}

function extractSwiftHex(line) {
  const match = line.match(/0x([0-9A-Fa-f]{6})/);
  return match ? '#' + match[1].toLowerCase() : null;
}

// ─── Main ───

function main() {
  // Check if tokens file exists
  if (!fs.existsSync(TOKENS_FILE)) {
    console.error('❌ figma-tokens.json not found. Export from Figma first.');
    console.error('   Use Claude Code: "export figma tokens" to generate it.');
    process.exit(1);
  }

  const tokens = JSON.parse(fs.readFileSync(TOKENS_FILE, 'utf8'));
  const themeContent = fs.readFileSync(THEME_FILE, 'utf8');
  const layoutContent = fs.readFileSync(LAYOUT_FILE, 'utf8');

  let driftCount = 0;
  let syncCount = 0;
  let missingCount = 0;

  console.log('╔════════════════════════════════════════╗');
  console.log('║    FIGMA → SWIFT TOKEN SYNC REPORT     ║');
  console.log('╚════════════════════════════════════════╝\n');

  // ─── Check Primitives ───
  console.log('── PRIMITIVES (Color Tokens) ──\n');

  for (const prim of tokens.primitives) {
    const swiftName = FIGMA_TO_SWIFT_COLOR[prim.name];
    if (!swiftName) {
      console.log(`  ⚠️  No Swift mapping for Figma primitive: ${prim.name}`);
      missingCount++;
      continue;
    }

    // Find in Swift file
    const regex = new RegExp(`static\\s+let\\s+${swiftName}\\b.*?0x([0-9A-Fa-f]{6})`);
    const match = themeContent.match(regex);

    if (!match) {
      console.log(`  ❌ MISSING in Swift: ${swiftName} (Figma: ${prim.hex})`);
      missingCount++;
      continue;
    }

    const swiftHex = '#' + match[1].toLowerCase();
    if (swiftHex !== prim.hex) {
      console.log(`  🔴 DRIFT: ${swiftName}`);
      console.log(`     Figma: ${prim.hex}  Swift: ${swiftHex}`);
      driftCount++;
    } else {
      syncCount++;
    }
  }

  // ─── Check Spacing ───
  console.log('\n── SPACING & RADIUS ──\n');

  for (const sp of tokens.spacing) {
    const swiftName = FIGMA_TO_SWIFT_SPACING[sp.name];
    if (!swiftName) {
      console.log(`  ⚠️  No Swift mapping for Figma spacing: ${sp.name}`);
      missingCount++;
      continue;
    }

    const regex = new RegExp(`static\\s+let\\s+${swiftName}\\s*:\\s*CGFloat\\s*=\\s*(\\d+(?:\\.\\d+)?)`);
    const match = layoutContent.match(regex);

    if (!match) {
      console.log(`  ❌ MISSING in Swift: ${swiftName} (Figma: ${sp.value})`);
      missingCount++;
      continue;
    }

    const swiftValue = parseFloat(match[1]);
    if (swiftValue !== sp.value) {
      console.log(`  🔴 DRIFT: ${swiftName}`);
      console.log(`     Figma: ${sp.value}  Swift: ${swiftValue}`);
      driftCount++;
    } else {
      syncCount++;
    }
  }

  // ─── Summary ───
  console.log('\n╔════════════════════════════════════════╗');
  console.log(`║  ✅ In sync:    ${String(syncCount).padStart(3)}                    ║`);
  console.log(`║  🔴 Drift:      ${String(driftCount).padStart(3)}                    ║`);
  console.log(`║  ❌ Missing:    ${String(missingCount).padStart(3)}                    ║`);
  console.log(`║  Total:         ${String(syncCount + driftCount + missingCount).padStart(3)}                    ║`);
  console.log('╚════════════════════════════════════════╝');

  if (driftCount > 0) {
    console.log('\n⚠️  Drift detected! Review changes above and update Swift code.');
    process.exit(1);
  } else {
    console.log('\n✅ All Figma tokens match Swift code.');
  }
}

main();
